  { text: "Type-safe, modern-tooling languages dominate the top spots", options: { breakLine: true, fontSize: 12, color: C.textDark, fontFace: "Calibri" } },
], {
  x: 6.5, y: 1.6, w: 3.0, h: 0.5, margin: 0,
});

// Three insight boxes
const insights = [
