  { title: "Modern DX", desc: "Strong tooling, package managers, and IDE support drive developer happiness", color: C.accent },
  { title: "The Gap", desc: "Top 2 score 198+ vs. C at 86 — a 2.3× satisfaction spread", color: C.secondary },
];

insights.forEach((ins, i) => {
