  { domain: "Data Processing & Analytics", lang: "Python",     share: "17%", langColor: LC.Python,     shareVal: 17 },
  { domain: "User Interface",              lang: "TypeScript", share: "62%", langColor: LC.TypeScript, shareVal: 62 },
  { domain: "Application Logic",           lang: "Java",       share: "55%", langColor: LC.Java,       shareVal: 55 },
  { domain: "APIs & Services",             lang: "Java",       share: "49%", langColor: LC.Java,       shareVal: 49 },
  { domain: "System Tools & Components",   lang: "C++",        share: "27%", langColor: LC["C++"],     shareVal: 27 },
];

// Build table rows
const headerRow = [
  { text: "Application Domain",       options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "left" } },
  { text: "Leading Language",          options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "center" } },
