}], {
  x: 0.4, y: 0.95, w: 5.6, h: 3.7,
  barDir: "bar",
  showTitle: false,
  showLegend: false,
  chartColors: [
    "94A3B8", "94A3B8",   // C, Dart
    "94A3B8", "94A3B8",   // Shell, Kotlin
    "94A3B8", "94A3B8",   // C++, Lua
    C.accent,              // Go
    LC.Python,             // Python
    LC.Rust,               // Rust
    LC.TypeScript,         // TypeScript
  ],
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 10,
  valAxisMinVal: 0,
  valAxisMaxVal: 220,
});

// Right side: Insight card
s4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 0.9, w: 3.4, h: 3.85,
