const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "JetBrains";
pres.title = "State of Developer Ecosystem 2024";

// ─── Color Palette ───
const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  lightBg:   "F1F5F9",
  white:     "FFFFFF",
  primary:   "0EA5E9",
  secondary: "6366F1",
  accent:    "10B981",
  danger:    "EF4444",
  textDark:  "1E293B",
  textLight: "F8FAFC",
  textMuted: "94A3B8",
  textSubtle:"64748B",
  border:    "CBD5E1",
  gridLine:  "E2E8F0",
};

// Language chart colors
const LC = {
  JavaScript: "EAB308",
  Python:     "3B82F6",
  "HTML/CSS": "F97316",
  SQL:        "8B5CF6",
  Java:       "EF4444",
  TypeScript: "06B6D4",
  Go:         "10B981",
  Rust:       "F43F5E",
  PHP:        "A855F7",
  Kotlin:     "EC4899",
  "C++":      "475569",
};

// Fresh shadow factory
const mkShadow = () => ({
  type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08
});

// ═══════════════════════════════════════════
// SLIDE 1: Title
// ═══════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { color: C.darkBg };

// Top accent bar
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.primary }
});

// Bottom accent bar
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: C.secondary }
});

// Left accent bar
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0.8, w: 0.06, h: 4.0, fill: { color: C.primary }
});

// Large decorative number
s1.addText("2024", {
  x: 6.5, y: 0.5, w: 3.0, h: 1.5,
  fontSize: 64, fontFace: "Georgia", color: C.darkBg2,
  bold: true, align: "right", margin: 0, transparency: 40,
});

// Title
s1.addText("State of Developer Ecosystem 2024", {
  x: 0.8, y: 1.3, w: 8.5, h: 1.0,
  fontSize: 36, fontFace: "Georgia", color: C.textLight,
  bold: true, margin: 0,
});

// Subtitle
s1.addText("Language Trends, Satisfaction, and Strategic Shifts", {
  x: 0.8, y: 2.35, w: 8.5, h: 0.6,
  fontSize: 20, fontFace: "Calibri", color: C.primary, margin: 0,
});

// Decorative line under subtitle
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0.8, y: 2.95, w: 2.0, h: 0.04, fill: { color: C.primary }
});

// Context block
s1.addText([
  { text: "Based on JetBrains’ annual survey of 23,262 developers worldwide", options: { breakLine: true, fontSize: 14, color: C.textMuted, fontFace: "Calibri" } },
  { text: "Covering programming languages, tooling preferences, AI sentiment, and career trends", options: { breakLine: true, fontSize: 13, color: C.textMuted, fontFace: "Calibri" } },
  { text: "Tracking 20 languages across 8 consecutive years (2017–2024)", options: { breakLine: true, fontSize: 13, color: C.textMuted, fontFace: "Calibri" } },
], {
  x: 0.8, y: 3.3, w: 8.5, h: 1.2, margin: 0,
});

// Bottom-right tag
s1.addText("jetbrains.com/lp/devecosystem-2024", {
  x: 5.5, y: 4.8, w: 4.0, h: 0.4,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted,
  align: "right", margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 2: Language Trends (Line Chart)
// ═══════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { color: C.lightBg };

// Title
s2.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
  x: 0.5, y: 0.25, w: 9.0, h: 0.55,
  fontSize: 22, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// White card for chart
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.3, y: 0.9, w: 9.4, h: 3.85,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Line chart
s2.addChart(pres.charts.LINE, [
  { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
  { name: "Python",     labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
  { name: "HTML/CSS",   labels: ["2017", "2020", "2022", "2024"], values: [60, 61, 54, 51] },
  { name: "SQL",        labels: ["2017", "2020", "2022", "2024"], values: [42, 56, 49, 48] },
  { name: "Java",       labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
  { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
  { name: "Go",         labels: ["2017", "2020", "2022", "2024"], values: [8, 19, 19, 18] },
  { name: "Rust",       labels: ["2017", "2020", "2022", "2024"], values: [0, 7, 9, 11] },
  { name: "PHP",        labels: ["2017", "2020", "2022", "2024"], values: [30, 27, 20, 17] },
  { name: "Kotlin",     labels: ["2017", "2020", "2022", "2024"], values: [2, 17, 16, 14] },
], {
  x: 0.4, y: 0.95, w: 9.2, h: 3.7,
  lineSize: 2,
  lineSmooth: false,
  showLegend: true,
  legendPos: "b",
  legendFontSize: 8,
  catAxisLabelColor: C.textSubtle,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  chartColors: [
    LC.JavaScript, LC.Python, LC["HTML/CSS"], LC.SQL, LC.Java,
    LC.TypeScript, LC.Go, LC.Rust, LC.PHP, LC.Kotlin
  ],
  showValue: false,
  valAxisMinVal: 0,
  valAxisMaxVal: 80,
  showTitle: false,
});

// Insight callout bar
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.3, y: 4.85, w: 9.4, h: 0.55,
  fill: { color: C.white }, shadow: mkShadow(),
});
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.3, y: 4.85, w: 0.06, h: 0.55, fill: { color: C.primary }
});
s2.addText([
  { text: "Key shifts: ", options: { bold: true, fontSize: 11, color: C.textDark, fontFace: "Calibri" } },
  { text: "JavaScript peaked at 70% (2020), now declining to 61% • Python rose from 32% to 57% • TypeScript tripled from 12% to 37% • PHP dropped from 30% to 17%", options: { fontSize: 11, color: C.textSubtle, fontFace: "Calibri" } },
], {
  x: 0.55, y: 4.85, w: 9.0, h: 0.55, valign: "middle", margin: 0,
});

// Footer
s2.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
  x: 0.5, y: 5.2, w: 9.0, h: 0.25,
  fontSize: 8, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 3: Primary Language
// ═══════════════════════════════════════════
const s3 = pres.addSlide();
s3.background = { color: C.lightBg };

// Title
s3.addText("Python Is Now the #1 Primary Language at 35%", {
  x: 0.5, y: 0.25, w: 9.0, h: 0.55,
  fontSize: 22, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// White card for chart
s3.addShape(pres.shapes.RECTANGLE, {
  x: 0.3, y: 0.9, w: 5.8, h: 3.85,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Horizontal bar chart - Primary Language
s3.addChart(pres.charts.BAR, [{
  name: "Primary Language",
  labels: ["SQL", "TypeScript", "JavaScript", "Java", "Python"],
  values: [17, 19, 28, 30, 35],
}], {
  x: 0.4, y: 0.95, w: 5.6, h: 3.7,
  barDir: "bar",
  showTitle: false,
  showLegend: false,
  chartColors: [LC.SQL, LC.TypeScript, LC.JavaScript, LC.Java, LC.Python],
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 11,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 10,
  valAxisMinVal: 0,
  valAxisMaxVal: 40,
});

// Right side: Adoption Intent card
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 0.9, w: 3.4, h: 3.85,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Accent top bar on card
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 0.9, w: 3.4, h: 0.06, fill: { color: C.secondary }
});

s3.addText("Adoption Intent", {
  x: 6.5, y: 1.1, w: 3.0, h: 0.4,
  fontSize: 16, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

s3.addText("Developers rarely plan to switch their primary stack", {
  x: 6.5, y: 1.5, w: 3.0, h: 0.5,
  fontSize: 11, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// Adoption intent mini-bars
const adoptData = [
  { lang: "Python", val: "6%", color: LC.Python },
  { lang: "TypeScript", val: "5%", color: LC.TypeScript },
  { lang: "Java", val: "4%", color: LC.Java },
  { lang: "SQL", val: "4%", color: LC.SQL },
];

adoptData.forEach((d, i) => {
  const yPos = 2.15 + i * 0.55;
  // Color dot
  s3.addShape(pres.shapes.OVAL, {
    x: 6.55, y: yPos + 0.05, w: 0.18, h: 0.18,
    fill: { color: d.color },
  });
  // Language name
  s3.addText(d.lang, {
    x: 6.85, y: yPos, w: 1.5, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: C.textDark, margin: 0,
  });
  // Percentage
  s3.addText(d.val, {
    x: 8.5, y: yPos, w: 0.8, h: 0.3,
