.5, valign: "middle", margin: 0,", " });", " ", " // Footer", " s5.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {", "-  x: 0.5, y: 5.2, w: 9.0, h: 0.25,", "+  x: 0.6, y: 5.25, w: 8.8, h: 0.2,", "   fontSize: 8, fontFace: "Calibri", color: C.textSubtle, margin: 0,", " });", " "]}, {"oldStart": 504, "oldLines": 17, "newStart": 522, "newLines": 17, "lines": [" ", " // Title", " s6.addText("What This Means for Your Technology Strategy in 2025", {", "-  x: 0.5, y: 0.3, w: 9.0, h: 0.6,", "+  x: 0.7, y: 0.35, w: 8.6, h: 0.55,", "   fontSize: 22, fontFace: "Georgia", color: C.textLight,", "   bold: true, margin: 0,", " });", " ", "-// Subtitle line", "+// Decorative line", " s6.addShape(pres.shapes.RECTANGLE, {", "-  x: 0.5, y: 0.9, w: 2.0, h: 0.04, fill: { color: C.primary }", "+  x: 0.7, y: 0.92, w: 1.8, h: 0.04, fill: { color: C.primary }", " });", " ", "-// 5 Strategic Takeaways", "+// 5 Strategic Takeaways with more spacing", " const takeaways = [", "   { num: "1", title: "Invest in Python for AI/ML teams", desc: "It is the undisputed leader — 31% AI/ML, 28% data science share", color: LC.Python },", "   { num: "2", title: "TypeScript is the future of frontend and full-stack", desc: "Highest satisfaction (199) and tripling usage since 2017", color: LC.TypeScript },"]}, {"oldStart": 524, "oldLines": 36, "newStart": 542, "newLines": 36, "lines": [" ];", " ", " takeaways.forEach((t, i) => {", "-  const yPos = 1.15 + i * 0.82;", "+  const yPos = 1.2 + i * 0.85;", " ", "-  // Number circle", "+  // Number circle (bright colored fill on dark bg = high contrast)", "   s6.addShape(pres.shapes.OVAL, {", "-    x: 0.55, y: yPos + 0.05, w: 0.4, h: 0.4,", "+    x: 0.75, y: yPos + 0.08, w: 0.38, h: 0.38,", "     fill: { color: t.color },", "   });", "   s6.addText(t.num, {", "-    x: 0.55, y: yPos + 0.05, w: 0.4, h: 0.4,", "-    fontSize: 16, fontFace: "Georgia", color: C.textLight,", "+    x: 0.75, y: yPos + 0.08, w: 0.38, h: 0.38,", "+    fontSize: 15, fo