  bold: true, margin: 0,
});

// Domain data
const domains = [
  { domain: "AI / Machine Learning",        lang: "Python",     share: "31%", langColor: LC.Python,     shareVal: 31 },
  { domain: "Data Science & Analytics",      lang: "Python",     share: "28%", langColor: LC.Python,     shareVal: 28 },
  { domain: "Integrating with APIs",         lang: "Python",     share: "38%", langColor: LC.Python,     shareVal: 38 },
  { domain: "Data Processing & Analytics",   lang: "Python",     share: "17%", langColor: LC.Python,     shareVal: 17 },
  { domain: "User Interface",                lang: "TypeScript", share: "62%", langColor: LC.TypeScript, shareVal: 62 },
  { domain: "Application Logic & Workflows", lang: "Java",       share: "55%", langColor: LC.Java,       shareVal: 55 },
  { domain: "APIs & Services",               lang: "Java",       share: "49%", langColor: LC.Java,       shareVal: 49 },
  { domain: "System Tools & Components",     lang: "C++",        share: "27%", langColor: LC["C++"],     shareVal: 27 },
];

// Build table rows
const headerRow = [
  { text: "Application Domain",  options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "left" } },
  { text: "Leading Language",     options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "center" } },
  { text: "Share",               options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "center" } },
];

const dataRows = domains.map((d, i) => {
  const rowBg = i % 2 === 0 ? C.white : "F8FAFC";
  return [
    { text: d.domain, options: { fill: { color: rowBg }, color: C.textDark, fontSize: 11, fontFace: "Calibri", align: "left" } },
    { text: d.lang,   options: { fill: { color: rowBg }, color: d.langColor, fontSize: 12, fontFace: "Calibri", bold: true, align: "center" } },
    { text: d.share,  options: { fill: { color: rowBg }, color: C.textDark, fontSize: 12, fontFace: "Georgia", bold: true, align: "center" } },
  ];
});

const tableData = [headerRow, ...dataRows];

s5.addTable(tableData, {
  x: 0.5, y: 0.85, w: 5.2,
  colW: [2.8, 1.3, 0.8],
  border: { pt: 0.5, color: C.border },
  rowH: [0.38, 0.38, 0.38, 0.38, 0.38, 0.38, 0.38, 0.38, 0.38],
});

// Right side: mini bar chart showing dominance
// For each domain, add a visual bar
s5.addShape(pres.shapes.RECTANGLE, {
  x: 6.0, y: 0.85, w: 3.5, h: 3.45,
  fill: { color: C.white }, shadow: mkShadow(),
});

s5.addShape(pres.shapes.RECTANGLE, {
  x: 6.0, y: 0.85, w: 3.5, h: 0.06, fill: { color: C.accent }
});

s5.addText("Dominance by Domain", {
  x: 6.2, y: 1.0, w: 3.1, h: 0.35,
  fontSize: 14, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

domains.forEach((d, i) => {
  const yPos = 1.5 + i * 0.35;
  const barMaxW = 2.0;
  const barW = (d.shareVal / 70) * barMaxW;

  // Background track
  s5.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: yPos, w: barMaxW, h: 0.18,
    fill: { color: "E2E8F0" },
  });
  // Filled bar
  s5.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: yPos, w: barW, h: 0.18,
    fill: { color: d.langColor, transparency: 20 },
  });
  // Share label
  s5.addText(d.share, {
    x: 8.5, y: yPos - 0.04, w: 0.8, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: C.textDark,
    bold: true, margin: 0,
  });
});

// Insight callout bar
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.55, w: 9.0, h: 0.5,
  fill: { color: C.white }, shadow: mkShadow(),
});
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.55, w: 0.06, h: 0.5, fill: { color: C.accent }
});
s5.addText([
  { text: "Key insight: ", options: { bold: true, fontSize: 11, color: C.textDark, fontFace: "Calibri" } },
  { text: "Language choice is driven by domain, not general preference. Python owns AI/data; TypeScript/JS own UI; Java owns backend services; C++ owns systems.", options: { fontSize: 11, color: C.textSubtle, fontFace: "Calibri" } },
], {
  x: 0.75, y: 4.55, w: 8.6, h: 0.5, valign: "middle", margin: 0,
});

// Footer
s5.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
  x: 0.6, y: 5.25, w: 8.8, h: 0.2,
  fontSize: 8, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 6: Strategic Takeaways
// ═══════════════════════════════════════════
const s6 = pres.addSlide();
s6.background = { color: C.darkBg };

// Top accent bar
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.primary }
});

// Bottom accent bar
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: C.secondary }
});

// Title
s6.addText("What This Means for Your Technology Strategy in 2025", {
  x: 0.7, y: 0.35, w: 8.6, h: 0.55,
  fontSize: 22, fontFace: "Georgia", color: C.textLight,
  bold: true, margin: 0,
});

// Decorative line
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 0.92, w: 1.8, h: 0.04, fill: { color: C.primary }
});

// 5 Strategic Takeaways with more spacing
const takeaways = [
  { num: "1", title: "Invest in Python for AI/ML teams", desc: "It is the undisputed leader — 31% AI/ML, 28% data science share", color: LC.Python },
  { num: "2", title: "TypeScript is the future of frontend and full-stack", desc: "Highest satisfaction (199) and tripling usage since 2017", color: LC.TypeScript },
  { num: "3", title: "Rust and Go are the growth plays for infrastructure", desc: "Performance + safety guarantees for systems and cloud-native tooling", color: LC.Rust },
  { num: "4", title: "PHP and Ruby hiring pools are shrinking", desc: "PHP dropped from 30% to 17%; Ruby from 10% to 4% — plan succession", color: C.danger },
  { num: "5", title: "Satisfaction correlates with type safety and modern tooling", desc: "Factor this into retention strategy — top languages all offer strong DX", color: C.accent },
];

takeaways.forEach((t, i) => {
  const yPos = 1.2 + i * 0.85;

  // Number circle (bright colored fill on dark bg = high contrast)
  s6.addShape(pres.shapes.OVAL, {
    x: 0.75, y: yPos + 0.08, w: 0.38, h: 0.38,
    fill: { color: t.color },
  });
  s6.addText(t.num, {
    x: 0.75, y: yPos + 0.08, w: 0.38, h: 0.38,
    fontSize: 15, fontFace: "Georgia", color: C.textLight,
    bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Title
  s6.addText(t.title, {
    x: 1.3, y: yPos, w: 8.0, h: 0.32,
    fontSize: 14, fontFace: "Calibri", color: C.textLight,
    bold: true, margin: 0,
  });

  // Description
  s6.addText(t.desc, {
    x: 1.3, y: yPos + 0.34, w: 8.0, h: 0.32,
    fontSize: 11, fontFace: "Calibri", color: C.textMuted, margin: 0,
  });
});

// Bottom tagline
s6.addText("jetbrains.com/lp/devecosystem-2024  •  n = 23,262 developers", {
  x: 0.7, y: 5.15, w: 8.6, h: 0.25,
  fontSize: 9, fontFace: "Calibri", color: C.textMuted,
  align: "right", margin: 0,
});

// ─── Write file ───
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("SUCCESS: /app/output/final_deck.pptx created"))
  .catch(err => console.error("ERROR:", err));

