  primary:   "0EA5E9",
  secondary: "6366F1",
  accent:    "10B981",
  danger:    "EF4444",
  textDark:  "1E293B",
  textLight: "F8FAFC",
  textMuted: "CBD5E1",   // Brighter for better contrast on dark
