], {
  x: 0.8, y: 3.1, w: 8.0, h: 1.1, margin: 0,
});

// Source tag
s1.addText("jetbrains.com/lp/devecosystem-2024", {
  x: 5.0, y: 4.6, w: 4.5, h: 0.35,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted,
  align: "right", margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 2: Language Trends (Line Chart)
// ═══════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { color: C.lightBg };

// Title
s2.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.5,
