  });
});

// Ecosystem lock-in callout
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.4, y: 3.95, w: 2.9, h: 0.35,
  fill: { color: "EEF2FF" },
});
s3.addText("Ecosystem lock-in keeps developers loyal to their chosen stacks", {
  x: 6.5, y: 3.95, w: 2.7, h: 0.35,
  fontSize: 9, fontFace: "Calibri", color: C.secondary,
  bold: true, valign: "middle", margin: 0,
});

// Footer
s3.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
