    { text: d.share,  options: { fill: { color: rowBg }, color: C.textDark, fontSize: 12, fontFace: "Georgia", bold: true, align: "center" } },
  ];
});

s5.addTable([headerRow, ...dataRows], {
  x: 0.5, y: 0.95, w: 5.0,
  colW: [2.6, 1.2, 0.7],
  border: { pt: 0.5, color: C.border },
  rowH: [0.36, 0.36, 0.36, 0.36, 0.36, 0.36, 0.36, 0.36, 0.36],
});

// Right: Dominance visual panel
s5.addShape(pres.shapes.RECTANGLE, {
  x: 5.8, y: 0.95, w: 3.7, h: 3.3,
  fill: { color: C.white }, shadow: mkShadow(),
});
s5.addShape(pres.shapes.RECTANGLE, {
  x: 5.8, y: 0.95, w: 3.7, h: 0.06, fill: { color: C.accent }
});

s5.addText("Dominance by Domain", {
  x: 6.0, y: 1.1, w: 3.3, h: 0.3,
  fontSize: 14, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// Domain bars with short labels
const shortLabels = ["AI/ML", "Data Sci", "API Integ", "Data Proc", "UI", "App Logic", "APIs/Svc", "Sys Tools"];
domains.forEach((d, i) => {
  const yPos = 1.55 + i * 0.33;
  const barMaxW = 1.8;
  const barW = (d.shareVal / 70) * barMaxW;

  // Short domain label
  s5.addText(shortLabels[i], {
    x: 5.95, y: yPos - 0.03, w: 0.8, h: 0.24,
