  s5.addText(d.share, {
    x: 8.75, y: yPos - 0.04, w: 0.5, h: 0.24,
    fontSize: 8, fontFace: "Calibri", color: C.textDark,
    bold: true, margin: 0,
  });
});

// Insight callout
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.5, w: 9.0, h: 0.5,
  fill: { color: C.white }, shadow: mkShadow(),
});
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.5, w: 0.06, h: 0.5, fill: { color: C.accent }
});
s5.addText([
  { text: "Key insight: ", options: { bold: true, fontSize: 11, color: C.textDark, fontFace: "Calibri" } },
  { text: "Language choice is driven by domain, not general preference. Python owns AI/data; TypeScript/JS own UI; Java owns backend; C++ owns systems.", options: { fontSize: 11, color: C.textSubtle, fontFace: "Calibri" } },
], {
  x: 0.75, y: 4.5, w: 8.6, h: 0.5, valign: "middle", margin: 0,
});

// Footer
s5.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
  x: 0.6, y: 5.25, w: 8.8, h: 0.2,
