});

// ═══════════════════════════════════════════
// SLIDE 6: Strategic Takeaways
// ═══════════════════════════════════════════
const s6 = pres.addSlide();
s6.background = { color: C.darkBg };

// Top accent bar
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.primary }
});
// Bottom accent bar
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: C.secondary }
});

// Title
s6.addText("What This Means for Your Technology Strategy in 2025", {
  x: 0.7, y: 0.35, w: 8.6, h: 0.5,
  fontSize: 22, fontFace: "Georgia", color: C.textLight,
  bold: true, margin: 0,
});

// Accent line
s6.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 0.88, w: 1.6, h: 0.04, fill: { color: C.primary }
});

// 5 Strategic Takeaways - tighter spacing to avoid overlap
const takeaways = [
  { num: "1", title: "Invest in Python for AI/ML teams", desc: "It is the undisputed leader - 31% AI/ML, 28% data science share", color: LC.Python },
  { num: "2", title: "TypeScript is the future of frontend and full-stack", desc: "Highest satisfaction (199) and tripling usage since 2017", color: LC.TypeScript },
  { num: "3", title: "Rust and Go are the growth plays for infrastructure", desc: "Performance + safety guarantees for systems and cloud-native tooling", color: LC.Rust },
  { num: "4", title: "PHP and Ruby hiring pools are shrinking", desc: "PHP dropped from 30% to 17%; Ruby from 10% to 4% - plan succession", color: C.danger },
  { num: "5", title: "Satisfaction correlates with type safety and modern tooling", desc: "Factor this into retention strategy - top languages all offer strong DX", color: C.accent },
];

takeaways.forEach((t, i) => {
  const yPos = 1.1 + i * 0.8;

  // Number circle with bright fill for high contrast
