const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "JetBrains";
pres.title = "State of Developer Ecosystem 2024";

// ─── Color Palette ───
const C = {
  darkBg:    "0F172A",
  darkBg2:   "1E293B",
  lightBg:   "F1F5F9",
  white:     "FFFFFF",
  primary:   "0EA5E9",
  secondary: "6366F1",
  accent:    "10B981",
  danger:    "EF4444",
  textDark:  "1E293B",
  textLight: "F8FAFC",
  textMuted: "CBD5E1",   // Brighter for better contrast on dark
  textSubtle:"64748B",
  border:    "CBD5E1",
  gridLine:  "E2E8F0",
};

// Language chart colors
const LC = {
  JavaScript: "EAB308",
  Python:     "3B82F6",
  "HTML/CSS": "F97316",
  SQL:        "8B5CF6",
  Java:       "EF4444",
  TypeScript: "06B6D4",
  Go:         "10B981",
  Rust:       "F43F5E",
  PHP:        "A855F7",
  Kotlin:     "EC4899",
  "C++":      "475569",
};

// Fresh shadow factory
const mkShadow = () => ({
  type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08
});

// ═══════════════════════════════════════════
// SLIDE 1: Title
// ═══════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { color: C.darkBg };

// Top accent bar
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.primary }
});
// Bottom accent bar
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: C.secondary }
});
// Left accent bar aligned with title
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 1.3, w: 0.06, h: 2.8, fill: { color: C.primary }
});

// Faded "2024" watermark
s1.addText("2024", {
  x: 5.8, y: 0.2, w: 3.7, h: 1.6,
  fontSize: 68, fontFace: "Georgia", color: C.darkBg2,
  bold: true, align: "right", margin: 0, transparency: 25,
});

// Title
s1.addText("State of Developer Ecosystem 2024", {
  x: 0.8, y: 1.3, w: 8.0, h: 0.85,
  fontSize: 34, fontFace: "Georgia", color: C.textLight,
  bold: true, margin: 0,
});

// Subtitle
s1.addText("Language Trends, Satisfaction, and Strategic Shifts", {
  x: 0.8, y: 2.2, w: 8.0, h: 0.45,
  fontSize: 19, fontFace: "Calibri", color: C.primary, margin: 0,
});

// Accent line under subtitle
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0.8, y: 2.7, w: 1.6, h: 0.04, fill: { color: C.primary }
});

// Context block
s1.addText([
  { text: "Based on JetBrains' annual survey of 23,262 developers worldwide", options: { breakLine: true, fontSize: 14, color: C.textMuted, fontFace: "Calibri" } },
  { text: "Covering programming languages, tooling preferences, AI sentiment, and career trends", options: { breakLine: true, fontSize: 13, color: C.textMuted, fontFace: "Calibri" } },
  { text: "Tracking 20 languages across 8 consecutive years (2017-2024)", options: { fontSize: 13, color: C.textMuted, fontFace: "Calibri" } },
], {
  x: 0.8, y: 3.1, w: 8.0, h: 1.1, margin: 0,
});

// Source tag
s1.addText("jetbrains.com/lp/devecosystem-2024", {
  x: 5.0, y: 4.6, w: 4.5, h: 0.35,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted,
  align: "right", margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 2: Language Trends (Line Chart)
// ═══════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { color: C.lightBg };

// Title
s2.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.5,
  fontSize: 21, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// White card for chart
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 0.95, w: 9.0, h: 3.4,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Line chart
s2.addChart(pres.charts.LINE, [
  { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
  { name: "Python",     labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
  { name: "HTML/CSS",   labels: ["2017", "2020", "2022", "2024"], values: [60, 61, 54, 51] },
  { name: "SQL",        labels: ["2017", "2020", "2022", "2024"], values: [42, 56, 49, 48] },
  { name: "Java",       labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
  { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
  { name: "Go",         labels: ["2017", "2020", "2022", "2024"], values: [8, 19, 19, 18] },
  { name: "Rust",       labels: ["2017", "2020", "2022", "2024"], values: [0, 7, 9, 11] },
  { name: "PHP",        labels: ["2017", "2020", "2022", "2024"], values: [30, 27, 20, 17] },
  { name: "Kotlin",     labels: ["2017", "2020", "2022", "2024"], values: [2, 17, 16, 14] },
], {
  x: 0.55, y: 1.0, w: 8.9, h: 3.3,
  lineSize: 2,
  lineSmooth: false,
  showLegend: true,
  legendPos: "b",
  legendFontSize: 8,
  catAxisLabelColor: C.textSubtle,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  chartColors: [
    LC.JavaScript, LC.Python, LC["HTML/CSS"], LC.SQL, LC.Java,
    LC.TypeScript, LC.Go, LC.Rust, LC.PHP, LC.Kotlin
  ],
  showValue: false,
  valAxisMinVal: 0,
  valAxisMaxVal: 80,
  showTitle: false,
});

// Insight callout bar
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.6, w: 9.0, h: 0.5,
  fill: { color: C.white }, shadow: mkShadow(),
});
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.6, w: 0.06, h: 0.5, fill: { color: C.primary }
});
s2.addText([
  { text: "Key shifts: ", options: { bold: true, fontSize: 11, color: C.textDark, fontFace: "Calibri" } },
  { text: "JS peaked 70% (2020) -> 61% • Python 32% -> 57% • TypeScript 12% -> 37% (3x) • PHP 30% -> 17%", options: { fontSize: 11, color: C.textSubtle, fontFace: "Calibri" } },
], {
  x: 0.75, y: 4.6, w: 8.6, h: 0.5, valign: "middle", margin: 0,
});

// Footer
s2.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
  x: 0.6, y: 5.25, w: 8.8, h: 0.2,
  fontSize: 8, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 3: Primary Language
// ═══════════════════════════════════════════
const s3 = pres.addSlide();
s3.background = { color: C.lightBg };

// Title
s3.addText("Python Is Now the #1 Primary Language at 35%", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.5,
  fontSize: 21, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// White card for chart (left)
s3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 0.95, w: 5.4, h: 3.5,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Horizontal bar chart
s3.addChart(pres.charts.BAR, [{
  name: "Primary Language",
  labels: ["SQL", "TypeScript", "JavaScript", "Java", "Python"],
  values: [17, 19, 28, 30, 35],
}], {
  x: 0.6, y: 1.0, w: 5.2, h: 3.4,
  barDir: "bar",
  showTitle: false,
  showLegend: false,
  chartColors: [LC.SQL, LC.TypeScript, LC.JavaScript, LC.Java, LC.Python],
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 11,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 10,
  valAxisMinVal: 0,
  valAxisMaxVal: 45,
});

// Right: Adoption Intent card
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.2, y: 0.95, w: 3.3, h: 3.5,
  fill: { color: C.white }, shadow: mkShadow(),
});
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.2, y: 0.95, w: 3.3, h: 0.06, fill: { color: C.secondary }
});

s3.addText("Adoption Intent", {
  x: 6.4, y: 1.15, w: 2.9, h: 0.35,
  fontSize: 15, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

s3.addText("Developers rarely plan to switch their primary stack", {
  x: 6.4, y: 1.5, w: 2.9, h: 0.45,
  fontSize: 11, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// Adoption intent items with more breathing room
const adoptData = [
  { lang: "Python",     val: "6%", color: LC.Python },
  { lang: "TypeScript", val: "5%", color: LC.TypeScript },
  { lang: "Java",       val: "4%", color: LC.Java },
  { lang: "SQL",        val: "4%", color: LC.SQL },
];

adoptData.forEach((d, i) => {
  const yPos = 2.1 + i * 0.45;
  s3.addShape(pres.shapes.OVAL, {
    x: 6.45, y: yPos + 0.06, w: 0.15, h: 0.15,
    fill: { color: d.color },
  });
  s3.addText(d.lang, {
    x: 6.7, y: yPos, w: 1.3, h: 0.28,
    fontSize: 12, fontFace: "Calibri", color: C.textDark, margin: 0,
  });
  s3.addText(d.val, {
    x: 8.3, y: yPos, w: 0.9, h: 0.28,
    fontSize: 15, fontFace: "Georgia", color: C.secondary,
    bold: true, align: "right", margin: 0,
  });
});

// Ecosystem lock-in callout
s3.addShape(pres.shapes.RECTANGLE, {
  x: 6.4, y: 3.95, w: 2.9, h: 0.35,
  fill: { color: "EEF2FF" },
});
s3.addText("Ecosystem lock-in keeps developers loyal to their chosen stacks", {
  x: 6.5, y: 3.95, w: 2.7, h: 0.35,
  fontSize: 9, fontFace: "Calibri", color: C.secondary,
  bold: true, valign: "middle", margin: 0,
});

// Footer
s3.addText("Source: JetBrains Developer Ecosystem Survey 2024, n=23,262", {
  x: 0.6, y: 5.25, w: 8.8, h: 0.2,
  fontSize: 8, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

// ═══════════════════════════════════════════
// SLIDE 4: Developer Satisfaction
// ═══════════════════════════════════════════
const s4 = pres.addSlide();
s4.background = { color: C.lightBg };

// Title (taller box for potential 2-line wrap)
s4.addText("TypeScript and Rust Top Developer Satisfaction, Nearly Tied at 199 vs 198", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.7,
  fontSize: 19, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

// White card for chart (left)
s4.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.1, w: 5.4, h: 3.35,
  fill: { color: C.white }, shadow: mkShadow(),
});

// Satisfaction bar chart
s4.addChart(pres.charts.BAR, [{
  name: "Satisfaction Score",
  labels: ["C", "Dart", "Shell", "Kotlin", "C++", "Lua", "Go", "Python", "Rust", "TypeScript"],
  values: [86, 93, 100, 113, 113, 118, 129, 151, 198, 199],
}], {
  x: 0.6, y: 1.15, w: 5.2, h: 3.25,
  barDir: "bar",
  showTitle: false,
  showLegend: false,
  chartColors: [
    "94A3B8", "94A3B8",
    "94A3B8", "94A3B8",
    "94A3B8", "94A3B8",
    C.accent,
    LC.Python,
    LC.Rust,
    LC.TypeScript,
  ],
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textSubtle,
  catAxisLabelFontSize: 10,
  valAxisLabelFontSize: 9,
  catGridLine: { style: "none" },
  valGridLine: { color: C.gridLine, size: 0.5 },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 10,
  valAxisMinVal: 0,
  valAxisMaxVal: 220,
});

// Right: Insight card
s4.addShape(pres.shapes.RECTANGLE, {
  x: 6.2, y: 1.1, w: 3.3, h: 3.35,
  fill: { color: C.white }, shadow: mkShadow(),
});
s4.addShape(pres.shapes.RECTANGLE, {
  x: 6.2, y: 1.1, w: 3.3, h: 0.06, fill: { color: C.accent }
});

s4.addText("What Drives Satisfaction?", {
  x: 6.4, y: 1.3, w: 2.9, h: 0.35,
  fontSize: 15, fontFace: "Georgia", color: C.textDark,
  bold: true, margin: 0,
});

s4.addText("Type-safe, modern-tooling languages dominate the top spots", {
  x: 6.4, y: 1.65, w: 2.9, h: 0.4,
  fontSize: 11, fontFace: "Calibri", color: C.textSubtle, margin: 0,
});

const insights = [
