  { domain: "User Interface",                lang: "TypeScript", share: "62%", langColor: LC.TypeScript, shareVal: 62 },
  { domain: "Application Logic",             lang: "Java",       share: "55%", langColor: LC.Java,       shareVal: 55 },
  { domain: "APIs & Services",               lang: "Java",       share: "49%", langColor: LC.Java,       shareVal: 49 },
