];

// Table
const headerRow = [
  { text: "Application Domain",  options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "left" } },
  { text: "Language",            options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "center" } },
  { text: "Share",               options: { fill: { color: C.darkBg }, color: C.textLight, bold: true, fontSize: 11, fontFace: "Calibri", align: "center" } },
];

