  return [
    { text: d.domain, options: { fill: { color: rowBg }, color: C.textDark, fontSize: 11, fontFace: "Calibri", align: "left" } },
    { text: d.lang,   options: { fill: { color: rowBg }, color: d.langColor, fontSize: 12, fontFace: "Calibri", bold: true, align: "center" } },
    { text: d.share,  options: { fill: { color: rowBg }, color: C.textDark, fontSize: 12, fontFace: "Georgia", bold: true, align: "center" } },
  ];
});

