  s5.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: yPos, w: barMaxW, h: 0.16,
    fill: { color: "E2E8F0" },
  });
  // Filled bar
  s5.addShape(pres.shapes.RECTANGLE, {
